match (status, parsed) {
    (ExecutionStatus::Ok, Some(sub)) => t.result = Some(sub),
    (ExecutionStatus::Interrupted, _) => t.exec = None,
    (_, _) => {
        if t.retries < ERROR_RETRIES && status == ExecutionStatus::Error {
            t.retries += 1;
            t.exec = None;
        } else {
            t.failed = Some(missing_submit(status, &error, result));
        }
    }
}

fn explore_tasks(&mut self) {
    let s = self.s;
    for t in &s.explore {
        if t.exec.is_none() && !t.abandoned && t.failed.is_none() {
            // Rule M1: read-only stages fan out; every ready explore spawns at once.
            let inputs = SpawnInputs {
                task: Some(format!("{}{}", t.task, s.added_context())),
                ..Default::default()
            };
            self.spawn(
                AgentName::Explore,
                ExploreRef(t.idx).purpose(),
                &t.project,
                s.project_session_dir(&t.project),
                inputs,
            );
        } else if let (Some(err), None, Some(exec), false, false) = (
            &t.failed,
            &t.gate,
            &t.exec,
            t.abandoned,
            // Rule H3: a helper's failure is its asker's answer, not a gate.
            matches!(t.origin, ExploreOrigin::Ask { .. }),
        ) {
            self.exec_failed_gate(exec, AgentName::Explore, &t.project, err);
        }
    }
}

ExecPurpose::Explore { task } => {
    if let Some(t) = self.explore.get_mut(*task as usize) {
        t.gate = None;
        if retry {
            t.failed = None;
            t.exec = None;
            t.retries = 0;
        } else {
            t.abandoned = true;
        }
    }
    ..
}
